const b = $('Webhook').first().json.body || {};
if (b.evento !== 'recepcion_material_faltante' || !Array.isArray(b.items) || b.items.length === 0) return [];
const correos = [...new Set($input.all().map((i) => String(i.json.email || '').trim().toLowerCase()).filter(Boolean))];
if (correos.length === 0) return [];

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const marca = (v) => (v ? '<b style="color:#b91c1c">Falta</b>' : '<span style="color:#15803d">OK</span>');
const r = b.recepcion || {};
const filas = b.items.map((it) => `<tr>
  <td style="padding:6px;border:1px solid #ddd">${esc(it.codigo || 'sin código')}</td>
  <td style="padding:6px;border:1px solid #ddd">${esc(it.producto)}${it.marca ? `<br><small>${esc(it.marca)}</small>` : ''}</td>
  <td style="padding:6px;border:1px solid #ddd;text-align:right">${esc(it.cantidad)}</td>
  <td style="padding:6px;border:1px solid #ddd;text-align:center">${it.nuevo ? (it.en_odoo ? 'Sí (primera llegada)' : 'Sí (no está en Odoo)') : 'No'}</td>
  <td style="padding:6px;border:1px solid #ddd;text-align:center">${marca(it.sin_imagen)}</td>
  <td style="padding:6px;border:1px solid #ddd;text-align:center">${marca(it.sin_flyer)}</td>
</tr>`).join('');

const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#111">
<p>Compras cargó un packing list de <b>${esc(r.sede)}</b>. Estos productos vienen en camino y les falta material:</p>
<p>Proveedor: <b>${esc(r.proveedor)}</b><br>Referencia: <b>${esc(r.referencia)}</b><br>Llegada estimada: <b>${esc(r.fecha_estimada ? String(r.fecha_estimada).slice(0, 10) : 'sin fecha')}</b><br>Cargado por: ${esc(r.cargado_por)}</p>
<p>${b.resumen.nuevos} nuevos · ${b.resumen.sin_imagen} sin imagen en Odoo · ${b.resumen.sin_flyer} sin flyer en el banco (de ${esc(r.total_productos)} productos del packing list)</p>
<table style="border-collapse:collapse"><tr style="background:#f3f4f6">
<th style="padding:6px;border:1px solid #ddd">Código</th><th style="padding:6px;border:1px solid #ddd">Producto</th><th style="padding:6px;border:1px solid #ddd">Cantidad</th><th style="padding:6px;border:1px solid #ddd">Nuevo</th><th style="padding:6px;border:1px solid #ddd">Imagen Odoo</th><th style="padding:6px;border:1px solid #ddd">Flyer</th></tr>${filas}</table>
<p><a href="${esc(b.link)}">Abrir el Banco de Flyers</a></p>
</div>`;

return [{ json: { to: correos.join(','), subject: `Productos por llegar sin imagen o flyer - ${r.referencia} (${r.sede})`, html } }];
